    29→export const loader = async ({ request }: LoaderFunctionArgs) => {
    30→  const { session, admin } = await authenticate.admin(request);
    31→  const shop = session.shop;
    32→
    33→  let config = await db.widgetConfig.findUnique({ where: { shop } });
    34→
    35→  if (!config) {
    36→    config = await db.widgetConfig.create({ data: { shop } });
    37→  }
    38→
    39→  // Ensure metafield is in sync (covers existing configs that were saved
    40→  // before the metafield feature was added)
    41→  const {
    42→    id: _id,
    43→    shop: _shop,
    44→    createdAt: _createdAt,
    45→    updatedAt: _updatedAt,
    46→    ...configData
    47→  } = config;
    48→  await syncConfigMetafield(admin, configData);
    49→
    50→  const themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
    51→
    52→  return { config, themeEditorUrl };
    53→};
    54→
    55→// Helper: sync widget config to a shop metafield so the storefront
    56→// liquid block can read it directly without needing an API call.
    57→async function syncConfigMetafield(
    58→  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
    59→  configData: Record<string, unknown>,
    60→) {
    61→  try {
    62→    const shopResponse = await admin.graphql(`query { shop { id } }`);
    63→    const shopJson: { data: { shop: { id: string } } } =
    64→      await shopResponse.json();
    65→    const shopGid = shopJson.data.shop.id;
    66→
    67→    await admin.graphql(
    68→      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
    69→        metafieldsSet(metafields: $metafields) {
    70→          metafields { id }
    71→          userErrors { field message }
    72→        }
    73→      }`,
    74→      {
    75→        variables: {
    76→          metafields: [
    77→            {
    78→              ownerId: shopGid,
    79→              namespace: "$app:zip_checker",
    80→              key: "widget_config",
    81→              type: "json",
    82→              value: JSON.stringify(configData),
    83→            },
    84→          ],
    85→        },
    86→      },
    87→    );
    88→  } catch (e) {
    89→    // Non-fatal — the API fallback still works
    90→    console.error("Failed to sync widget config metafield:", e);
    91→  }
    92→}
