    94→export const action = async ({ request }: ActionFunctionArgs) => {
    95→  const { session, admin } = await authenticate.admin(request);
    96→  const shop = session.shop;
    97→  const formData = await request.formData();
    98→  const intent = formData.get("intent");
    99→
   100→  if (intent === "save") {
   101→    const data = {
   102→      position: String(formData.get("position") || "inline"),
   103→      primaryColor: String(formData.get("primaryColor") || "#008060"),
   104→      successColor: String(formData.get("successColor") || "#008060"),
   105→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
   106→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
   107→      textColor: String(formData.get("textColor") || "#202223"),
   108→      heading: String(formData.get("heading") || "Check Delivery Availability"),
   109→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
   110→      buttonText: String(formData.get("buttonText") || "Check"),
   111→      successMessage: String(
   112→        formData.get("successMessage") ||
   113→          "Great news! We deliver to your area.",
   114→      ),
   115→      errorMessage: String(
   116→        formData.get("errorMessage") ||
   117→          "Sorry, we don't deliver to this area yet.",
   118→      ),
   119→      notFoundMessage: String(
   120→        formData.get("notFoundMessage") ||
   121→          "This zip code was not found in our system.",
   122→      ),
   123→      showEta: formData.get("showEta") === "true",
   124→      showZone: formData.get("showZone") === "true",
   125→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
   126→      borderRadius: String(formData.get("borderRadius") || "8"),
   127→      customCss: String(formData.get("customCss") || "") || null,
   128→    };
   129→
   130→    await db.widgetConfig.upsert({
   131→      where: { shop },
   132→      create: { shop, ...data },
   133→      update: data,
   134→    });
   135→
   136→    // Sync to shop metafield so storefront reads config without API call
   137→    await syncConfigMetafield(admin, data);
   138→
   139→    return { success: true };
   140→  }
   141→
   142→  if (intent === "reset") {
   143→    const resetData = {
   144→      position: "inline",
   145→      primaryColor: "#008060",
   146→      successColor: "#008060",
   147→      errorColor: "#D72C0D",
   148→      backgroundColor: "#FFFFFF",
   149→      textColor: "#202223",
   150→      heading: "Check Delivery Availability",
   151→      placeholder: "Enter your zip code",
   152→      buttonText: "Check",
   153→      successMessage: "Great news! We deliver to your area.",
   154→      errorMessage: "Sorry, we don't deliver to this area yet.",
   155→      notFoundMessage: "This zip code was not found in our system.",
   156→      showEta: true,
   157→      showZone: false,
   158→      showWaitlistOnFailure: false,
   159→      borderRadius: "8",
   160→      customCss: null,
   161→    };
   162→
   163→    await db.widgetConfig.upsert({
   164→      where: { shop },
   165→      create: { shop },
   166→      update: resetData,
   167→    });
   168→
   169→    // Sync reset config to metafield
   170→    await syncConfigMetafield(admin, resetData);
   171→
   172→    return { success: true, action: "reset" };
   173→  }
   174→
   175→  return null;
   176→};
