   198→// ── CSS generator — mirrors the Liquid block CSS exactly ────────────────────
   199→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
   200→  const rad = cfg.borderRadius + "px";
   201→  return (
   202→    "#" + wid + "{" +
   203→      "background:" + cfg.backgroundColor + ";" +
   204→      "color:" + cfg.textColor + ";" +
   205→      "border-radius:" + rad + ";" +
   206→      "padding:24px;" +
   207→      "border:1px solid #e1e3e5;" +
   208→      "max-width:400px;" +
   209→      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
   210→      "box-sizing:border-box;" +
   211→    "}" +
   212→    "#" + wid + " *{box-sizing:border-box}" +
   213→    "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
   214→    "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
   215→    "#" + wid + " .zcc-input{" +
   216→      "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
   217→      "border-radius:" + rad + ";font-size:14px;outline:none;" +
   218→      "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
   219→    "}" +
   220→    "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
   221→    "#" + wid + " .zcc-btn{" +
   222→      "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
   223→      "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
   224→      "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
   225→    "}" +
   226→    "#" + wid + " .zcc-btn:hover{opacity:.9}" +
   227→    "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
   228→    "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
   229→    "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
   230→    "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
   231→    "#" + wid + " .zcc-wl{margin-top:10px}" +
   232→    "#" + wid + " .zcc-wl-input{" +
   233→      "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
   234→      "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
   235→    "}" +
   236→    "#" + wid + " .zcc-wl-btn{" +
   237→      "background:" + cfg.errorColor + ";color:#fff;border:none;" +
   238→      "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
   239→      "cursor:pointer;width:100%;font-weight:600" +
   240→    "}" +
   241→    (cfg.customCss || "")
   242→  );
   243→}
