   245→// ── Live Preview component (defined outside WidgetPage to avoid remounting) ─
   246→function WidgetPreview({
   247→  cfg,
   248→  previewState,
   249→}: {
   250→  cfg: WidgetConfig;
   251→  previewState: "idle" | "success" | "error" | "notfound";
   252→}) {
   253→  const wid = "zcc-admin-preview";
   254→  const css = buildWidgetCss(wid, cfg);
   255→
   256→  const resultClass =
   257→    previewState === "success" ? "ok" :
   258→    (previewState === "error" || previewState === "notfound") ? "fail" : "";
   259→
   260→  const resultMessage =
   261→    previewState === "success" ? cfg.successMessage :
   262→    previewState === "error" ? cfg.errorMessage :
   263→    previewState === "notfound" ? cfg.notFoundMessage : null;
   264→
   265→  const widgetHtml = (
   266→    <div id={wid}>
   267→      <p className="zcc-heading">{cfg.heading}</p>
   268→      <div className="zcc-row">
   269→        <input
   270→          className="zcc-input"
   271→          type="text"
   272→          placeholder={cfg.placeholder}
   273→          readOnly
   274→        />
   275→        <button className="zcc-btn" type="button">
   276→          {cfg.buttonText}
   277→        </button>
   278→      </div>
   279→      {resultMessage && (
   280→        <div className={`zcc-result ${resultClass}`}>
   281→          {resultMessage}
   282→          {previewState === "success" && cfg.showEta && (
   283→            <div className="zcc-meta">Estimated delivery: 2–3 business days</div>
   284→          )}
   285→          {previewState === "success" && cfg.showZone && (
   286→            <div className="zcc-meta">Zone: Manhattan</div>
   287→          )}
   288→          {(previewState === "error" || previewState === "notfound") &&
   289→            cfg.showWaitlistOnFailure && (
   290→              <div className="zcc-wl">
   291→                <input
   292→                  className="zcc-wl-input"
   293→                  type="email"
   294→                  placeholder="Enter email to join waitlist"
   295→                  readOnly
   296→                />
   297→                <button className="zcc-wl-btn" type="button">
   298→                  Join Waitlist
   299→                </button>
   300→              </div>
   301→            )}
   302→        </div>
   303→      )}
   304→    </div>
   305→  );
   306→
   307→  // Floating position: show mock fixed button + collapsible panel concept
   308→  if (cfg.position === "floating") {
   309→    return (
   310→      <>
   311→        {/* eslint-disable-next-line react/no-danger */}
   312→        <style dangerouslySetInnerHTML={{ __html: css }} />
   313→        <div
   314→          style={{
   315→            position: "relative",
   316→            minHeight: "120px",
   317→            background: "#f6f6f7",
   318→            borderRadius: "8px",
   319→            padding: "12px",
   320→          }}
   321→        >
   322→          <Text as="p" variant="bodySm" tone="subdued">
   323→            The widget will appear as a fixed button in the bottom-right corner of your storefront.
   324→          </Text>
   325→          <div
   326→            style={{
   327→              position: "absolute",
   328→              bottom: "12px",
   329→              right: "12px",
   330→              display: "flex",
   331→              flexDirection: "column",
   332→              alignItems: "flex-end",
   333→              gap: "8px",
   334→            }}
   335→          >
   336→            <div id={wid} style={{ maxWidth: "300px" }}>
   337→              <p className="zcc-heading" style={{ marginBottom: "12px" }}>
   338→                {cfg.heading}
   339→              </p>
   340→              <div className="zcc-row">
   341→                <input
   342→                  className="zcc-input"
   343→                  type="text"
   344→                  placeholder={cfg.placeholder}
   345→                  readOnly
   346→                />
   347→                <button className="zcc-btn" type="button">
   348→                  {cfg.buttonText}
   349→                </button>
   350→              </div>
   351→            </div>
   352→            <button
   353→              type="button"
   354→              style={{
   355→                background: cfg.primaryColor,
   356→                color: "#fff",
   357→                border: "none",
   358→                borderRadius: "50px",
   359→                padding: "10px 18px",
   360→                fontSize: "13px",
   361→                fontWeight: 600,
   362→                cursor: "pointer",
   363→                boxShadow: "0 4px 12px rgba(0,0,0,.2)",
   364→              }}
   365→            >
   366→              📍 Check Delivery
   367→            </button>
   368→          </div>
   369→        </div>
   370→      </>
   371→    );
   372→  }
   373→
   374→  // Popup position: show trigger button + hint of overlay
   375→  if (cfg.position === "popup") {
   376→    return (
   377→      <>
   378→        {/* eslint-disable-next-line react/no-danger */}
   379→        <style dangerouslySetInnerHTML={{ __html: css }} />
   380→        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
   381→          <Text as="p" variant="bodySm" tone="subdued">
   382→            A trigger button will appear in the section. Clicking it opens a centered popup.
   383→          </Text>
   384→          <div>
   385→            <button
   386→              type="button"
   387→              style={{
   388→                background: cfg.primaryColor,
   389→                color: "#fff",
   390→                border: "none",
   391→                borderRadius: cfg.borderRadius + "px",
   392→                padding: "10px 24px",
   393→                fontSize: "14px",
   394→                fontWeight: 600,
   395→                cursor: "pointer",
   396→              }}
   397→            >
   398→              Check Delivery Availability
   399→            </button>
   400→          </div>
   401→          <div
   402→            style={{
   403→              background: "rgba(0,0,0,.06)",
   404→              borderRadius: "8px",
   405→              padding: "12px",
   406→              border: "2px dashed #c9cccf",
   407→            }}
   408→          >
   409→            <Text as="p" variant="bodySm" tone="subdued">
   410→              Popup content preview:
   411→            </Text>
   412→            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
   413→          </div>
   414→        </div>
   415→      </>
   416→    );
   417→  }
   418→
   419→  // Inline (default)
   420→  return (
   421→    <>
   422→      {/* eslint-disable-next-line react/no-danger */}
   423→      <style dangerouslySetInnerHTML={{ __html: css }} />
   424→      {widgetHtml}
   425→    </>
   426→  );
   427→}
