   429→// ── Page component ───────────────────────────────────────────────────────────
   430→export default function WidgetPage() {
   431→  const { config, themeEditorUrl } = useLoaderData<typeof loader>();
   432→  const fetcher = useFetcher<typeof action>();
   433→  const shopify = useAppBridge();
   434→  const navigate = useNavigate();
   435→
   436→  const c = config as WidgetConfig;
   437→
   438→  // Form state initialized from DB
   439→  const [position, setPosition] = useState(c.position);
   440→  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
   441→  const [successColor, setSuccessColor] = useState(c.successColor);
   442→  const [errorColor, setErrorColor] = useState(c.errorColor);
   443→  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
   444→  const [textColor, setTextColor] = useState(c.textColor);
   445→  const [heading, setHeading] = useState(c.heading);
   446→  const [placeholder, setPlaceholder] = useState(c.placeholder);
   447→  const [buttonText, setButtonText] = useState(c.buttonText);
   448→  const [successMessage, setSuccessMessage] = useState(c.successMessage);
   449→  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
   450→  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
   451→  const [showEta, setShowEta] = useState(c.showEta);
   452→  const [showZone, setShowZone] = useState(c.showZone);
   453→  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
   454→    c.showWaitlistOnFailure,
   455→  );
   456→  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
   457→  const [customCss, setCustomCss] = useState(c.customCss || "");
   458→
   459→  // Unsaved changes tracking
   460→  const [isDirty, setIsDirty] = useState(false);
   461→
   462→  // Preview state
   463→  const [previewState, setPreviewState] = useState<
   464→    "idle" | "success" | "error" | "notfound"
   465→  >("idle");
   466→
   467→  const isSaving =
   468→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
   469→
   470→  // Clear dirty flag after successful save
   471→  useEffect(() => {
   472→    if (
   473→      fetcher.state === "idle" &&
   474→      fetcher.data &&
   475→      "success" in fetcher.data &&
   476→      fetcher.data.success
   477→    ) {
   478→      setIsDirty(false);
   479→    }
   480→  }, [fetcher.state, fetcher.data]);
   481→
   482→  // Dirty-aware setters
   483→  const mark = useCallback(() => setIsDirty(true), []);
   484→  const handlePositionChange = useCallback((v: string) => { setPosition(v); mark(); }, [mark]);
   485→  const handlePrimaryColorChange = useCallback((v: string) => { setPrimaryColor(v); mark(); }, [mark]);
   486→  const handleSuccessColorChange = useCallback((v: string) => { setSuccessColor(v); mark(); }, [mark]);
   487→  const handleErrorColorChange = useCallback((v: string) => { setErrorColor(v); mark(); }, [mark]);
   488→  const handleBackgroundColorChange = useCallback((v: string) => { setBackgroundColor(v); mark(); }, [mark]);
   489→  const handleTextColorChange = useCallback((v: string) => { setTextColor(v); mark(); }, [mark]);
   490→  const handleHeadingChange = useCallback((v: string) => { setHeading(v); mark(); }, [mark]);
   491→  const handlePlaceholderChange = useCallback((v: string) => { setPlaceholder(v); mark(); }, [mark]);
   492→  const handleButtonTextChange = useCallback((v: string) => { setButtonText(v); mark(); }, [mark]);
   493→  const handleSuccessMessageChange = useCallback((v: string) => { setSuccessMessage(v); mark(); }, [mark]);
   494→  const handleErrorMessageChange = useCallback((v: string) => { setErrorMessage(v); mark(); }, [mark]);
   495→  const handleNotFoundMessageChange = useCallback((v: string) => { setNotFoundMessage(v); mark(); }, [mark]);
   496→  const handleShowEtaChange = useCallback((v: boolean) => { setShowEta(v); mark(); }, [mark]);
   497→  const handleShowZoneChange = useCallback((v: boolean) => { setShowZone(v); mark(); }, [mark]);
   498→  const handleShowWaitlistChange = useCallback((v: boolean) => { setShowWaitlistOnFailure(v); mark(); }, [mark]);
   499→  const handleBorderRadiusChange = useCallback((v: string) => { setBorderRadius(v); mark(); }, [mark]);
   500→  const handleCustomCssChange = useCallback((v: string) => { setCustomCss(v); mark(); }, [mark]);
   501→
   502→  const handleSave = useCallback(() => {
   503→    const fd = new FormData();
   504→    fd.set("intent", "save");
   505→    fd.set("position", position);
   506→    fd.set("primaryColor", primaryColor);
   507→    fd.set("successColor", successColor);
   508→    fd.set("errorColor", errorColor);
   509→    fd.set("backgroundColor", backgroundColor);
   510→    fd.set("textColor", textColor);
   511→    fd.set("heading", heading);
   512→    fd.set("placeholder", placeholder);
   513→    fd.set("buttonText", buttonText);
   514→    fd.set("successMessage", successMessage);
   515→    fd.set("errorMessage", errorMessage);
   516→    fd.set("notFoundMessage", notFoundMessage);
   517→    fd.set("showEta", String(showEta));
   518→    fd.set("showZone", String(showZone));
   519→    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
   520→    fd.set("borderRadius", borderRadius);
   521→    fd.set("customCss", customCss);
   522→    fetcher.submit(fd, { method: "POST" });
   523→    shopify.toast.show("Widget settings saved");
   524→  }, [
   525→    position, primaryColor, successColor, errorColor, backgroundColor,
   526→    textColor, heading, placeholder, buttonText, successMessage, errorMessage,
   527→    notFoundMessage, showEta, showZone, showWaitlistOnFailure, borderRadius,
   528→    customCss, fetcher, shopify,
   529→  ]);
   530→
   531→  const DEFAULTS = {
   532→    position: "inline",
   533→    primaryColor: "#008060",
   534→    successColor: "#008060",
   535→    errorColor: "#D72C0D",
   536→    backgroundColor: "#FFFFFF",
   537→    textColor: "#202223",
   538→    heading: "Check Delivery Availability",
   539→    placeholder: "Enter your zip code",
   540→    buttonText: "Check",
   541→    successMessage: "Great news! We deliver to your area.",
   542→    errorMessage: "Sorry, we don't deliver to this area yet.",
   543→    notFoundMessage: "This zip code was not found in our system.",
   544→    showEta: true,
   545→    showZone: false,
   546→    showWaitlistOnFailure: false,
   547→    borderRadius: "8",
   548→    customCss: "",
   549→  };
   550→
   551→  const handleReset = useCallback(() => {
