// Helper: sync widget config to a shop metafield so the storefront
// liquid block can read it directly without needing an API call.
async function syncConfigMetafield(
  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
  configData: Record<string, unknown>,
) {
  try {
    const shopResponse = await admin.graphql(`query { shop { id } }`);
    const shopJson: { data: { shop: { id: string } } } =
      await shopResponse.json();
    const shopGid = shopJson.data.shop.id;

    await admin.graphql(
      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
        metafieldsSet(metafields: $metafields) {
          metafields { id }
          userErrors { field message }
        }
      }`,
      {
        variables: {
          metafields: [
            {
              ownerId: shopGid,
              namespace: "$app:zip_checker",
              key: "widget_config",
              type: "json",
              value: JSON.stringify(configData),
            },
          ],
        },
      },
    );
  } catch (e) {
    // Non-fatal — the API fallback still works
    console.error("Failed to sync widget config metafield:", e);
  }
}

