    55→// Helper: sync widget config to an App Installation metafield so the
    56→// storefront Liquid block can read it via app.metafields.zip_checker.widget_config.value
    57→//
    58→// IMPORTANT: ownerId MUST be the App Installation GID (not the Shop GID).
    59→// app.metafields in Liquid only surfaces metafields owned by the App Installation.
    60→// Using the Shop GID writes to shop metafields which are invisible to app.metafields.
    61→async function syncConfigMetafield(
    62→  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
    63→  configData: Record<string, unknown>,
    64→) {
    65→  try {
    66→    // Step 1: get the App Installation GID
    67→    const installResponse = await admin.graphql(
    68→      `query { currentAppInstallation { id } }`,
    69→    );
    70→    const installJson = (await installResponse.json()) as {
    71→      data: { currentAppInstallation: { id: string } };
    72→    };
    73→    const appInstallationGid = installJson.data.currentAppInstallation.id;
    74→
    75→    // Step 2: write the metafield to the App Installation
    76→    // Namespace must be plain "zip_checker" (no "$app:" prefix) for App Installation metafields.
    77→    // The Liquid block reads: app.metafields.zip_checker.widget_config.value
    78→    const metaResponse = await admin.graphql(
    79→      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
    80→        metafieldsSet(metafields: $metafields) {
    81→          metafields { id namespace key }
    82→          userErrors { field message }
    83→        }
    84→      }`,
    85→      {
    86→        variables: {
    87→          metafields: [
    88→            {
    89→              ownerId: appInstallationGid,
    90→              namespace: "zip_checker",
    91→              key: "widget_config",
    92→              type: "json",
    93→              value: JSON.stringify(configData),
    94→            },
    95→          ],
    96→        },
    97→      },
    98→    );
    99→    const metaJson = (await metaResponse.json()) as {
   100→      data: {
   101→        metafieldsSet: {
   102→          metafields: { id: string; namespace: string; key: string }[];
   103→          userErrors: { field: string; message: string }[];
   104→        };
   105→      };
   106→    };
   107→
   108→    if (metaJson.data.metafieldsSet.userErrors.length > 0) {
   109→      console.error(
   110→        "metafieldsSet userErrors:",
   111→        metaJson.data.metafieldsSet.userErrors,
   112→      );
   113→    }
   114→  } catch (e) {
   115→    // Non-fatal — the API fallback still works
   116→    console.error("Failed to sync widget config metafield:", e);
   117→  }
   118→}
